function Verification(props){
  const {React,ui,invoke,input,state,view,patch,go,mutate,readOnly}=props;
  const current=one(state.items,view.id);
  const mode=view.tab||(current?.kind==="execution"?"Executions":current?.kind==="evidence"?"Evidence":"Measures");
  const options={React,ui}, m=state.metrics;
  const group=({Measures:"measure",Executions:"execution",Evidence:"evidence"})[mode];
  const candidates=state.items.filter(x=>x.kind===group&&(!view.process||x.process===view.process)&&matches(x,view.query)&&(!view.statusFilter||group!=="measure"||x.status===view.statusFilter));
  candidates.sort((a,b)=>a.code.localeCompare(b.code,"en",{numeric:true}));
  const picked=current&&["measure","execution","evidence"].includes(current.kind)?current:candidates.find(i=>i.code==="VM-031")??candidates[0];
  const detail=useResource(React,invoke,"detail",{...input,id:picked?.id},Boolean(picked));
  const d=detail.value, page=view.page??0;
  function createRun(){
    if(!d?.item.measure)return;
    ask(props,"Record execution for "+picked.code,[
      fieldSpec("outcome","Outcome","Passed",{options:["Passed","Failed","Blocked"]}),fieldSpec("observed","Observed result"),fieldSpec("environment","Environment",d.item.measure.environment),
      fieldSpec("reason","Result rationale","",{multiline:true}),fieldSpec("evidence","Evidence or run log","",{multiline:true,required:false,max:20000})
    ],v=>mutate({name:"run",id:picked.id,...v}));
  }
  return <>
    <Heading React={React} title="Verification & Evidence" sub={(view.process?view.process+" · ":"")+projectSubtitle(props)+" · Scope, execution and supporting records."} actions={<Btn {...options} primary icon="plus" disabled={readOnly||!d?.item.measure} onClick={createRun}>Record execution</Btn>}/>
    <div className="ell-metrics"><Metric React={React} label="Measures planned" ratio={m.execution.d} note={view.baseline||"Working set"}/><Metric React={React} label="Execution coverage" ratio={m.execution}/><Metric React={React} label="Pass rate" ratio={m.pass} note={m.pass.n+" / "+m.pass.d+" final outcomes"}/><Metric React={React} label="Requirement mapping" ratio={m.mapped}/></div>
    <div className="ell-split">
      <Panel React={React} title={"Verification "+mode.toLowerCase()} sub={candidates.length+" matching artifacts"} action={<Toggle React={React} label="Verification views" options={["Measures","Executions","Evidence"]} value={mode} onChange={tab=>patch({tab,id:"",page:0,query:""})}/>}>
        <div className="ell-toolbar"><Search React={React} label={"Find "+group} value={view.query} onChange={query=>patch({query,page:0,id:""})}/>
          <Select React={React} hidden label="Verification process" items={[["","All processes"],...state.processes.filter(p=>p.route==="verification").map(p=>[p.code,p.code])]} value={view.process} onChange={process=>patch({process,page:0,id:""})}/>
          {mode==="Measures"&&<Select React={React} hidden label="Verification result" items={[["","All results"],"Passed","Failed","Blocked","Retest required","Not run"]} value={view.statusFilter} onChange={statusFilter=>patch({statusFilter,page:0,id:""})}/>}
          {view.baseline&&<button className="ell-toggle-plain" onClick={()=>patch({baseline:"",page:0})}>Working set</button>}
        </div>
        <Table React={React} label={"Verification "+mode.toLowerCase()} columns={["Artifact","Process",group==="measure"?"Current status":"Review",group==="measure"?"Latest execution":"Owner"]}>{candidates.slice(page*10,(page+1)*10).map(item=><tr key={item.id} data-selected={picked?.id===item.id}><td><ItemButton React={React} item={item} onClick={()=>patch({id:item.id})}/></td><td>{item.process}</td><td><Badge React={React} text={item.status??item.review}/></td><td>{item.execution??item.history??ownerName(state.users,item.owner)}</td></tr>)}</Table>
        {!candidates.length&&<Empty {...options} text="No verification artifacts match"/>}<Pages {...options} size={10} page={page} total={candidates.length} onChange={page=>patch({page})}/>
        <div className="ell-footer"><Btn {...options} icon="layers" onClick={()=>go("baselines")}>Compare baseline revisions</Btn></div>
      </Panel>
      <Panel React={React} className="ell-inspect">
        {!picked&&<Empty {...options} text="Select an artifact"/>}
        <Loading {...options} state={detail}>{({item,runs,connected,verification,evidenceBaseline})=>{
          const vm=item.measure, vx=item.execution, ev=item.evidence;
          return <>
            <div className="ell-between"><code>{item.code}</code><Badge React={React} text={verification?.status??vx?.result.outcome??item.review}/></div><h2>{item.title}</h2><small>{item.process} · Revision {item.revision}</small>
            {vm&&<>
              <p className="ell-text">{item.body}</p><Fact React={React} label="Method">{vm.method}</Fact><Fact React={React} label="Acceptance">{vm.criterion}</Fact><Fact React={React} label="Environment">{vm.environment}</Fact><Fact React={React} label="Preconditions">{vm.preconditions}</Fact>
              <details className="ell-details"><summary>Procedure</summary><ol>{vm.procedure.map(p=><li key={p}>{p}</li>)}</ol></details>
              <h3 className="ell-stack-title">Execution history</h3>{runs.length?runs.slice(0,8).map(run=><div key={run.id} className="ell-link-row"><ItemButton React={React} item={run} onClick={()=>patch({id:run.id,tab:"Executions",query:"",page:0})}/><div className="ell-between"><small>{run.execution.scope+" · Measure r"+run.execution.measureRevision}</small><Badge React={React} text={run.execution.result.outcome}/></div></div>):<p className="ell-text">No execution has been recorded.</p>}
              <div className="ell-stack"><Btn {...options} disabled={readOnly} onClick={()=>reviseDialog(props,item)}>Edit verification specification</Btn></div>
            </>}
            {vx&&<>
              <Fact React={React} label="Run scope">{vx.scope}</Fact><Fact React={React} label="Measure revision">{vx.measureRevision}</Fact><Fact React={React} label="Environment">{vx.environment}</Fact>{vx.criterion&&<Fact React={React} label="Acceptance in this run">{vx.criterion}</Fact>}<Fact React={React} label="Observed">{vx.result.observed}</Fact><p className="ell-text">{vx.result.reason}</p>
              {connected.filter(l=>l.peer.kind==="evidence").map(l=><div className="ell-link-row" key={l.id}><ItemButton React={React} item={l.peer} onClick={()=>patch({id:l.peer.id,tab:"Evidence",page:0,query:""})}/><Btn {...options} icon="file" onClick={()=>patch({id:l.peer.id,tab:"Evidence",page:0,query:""})}>Open evidence preview</Btn></div>)}
              {vx.result.outcome==="Failed"&&<div className="ell-stack"><Btn {...options} disabled={readOnly} onClick={()=>ask(props,"Create problem report",[fieldSpec("title","Title",item.title),fieldSpec("severity","Severity","Major",{options:["Critical","Major","Moderate","Minor"]}),fieldSpec("action","Planned corrective action","",{multiline:true})],v=>mutate({name:"problem",id:item.id,...v}))}>Create problem report</Btn></div>}
            </>}
            {ev&&<><p className="ell-text">{item.body}</p>{ev.waveform?<Waveform React={React} points={ev.waveform}/>:<pre className="ell-evidence-preview">{ev.content}</pre>}
              <Fact React={React} label="Evidence file">{ev.filename}</Fact><div className="ell-stack"><Btn {...options} icon="download" primary onClick={()=>openAsset(props,item.id)}>Download evidence file</Btn><Btn {...options} onClick={()=>patch({id:ev.execution,tab:"Executions",page:0,query:""})}>Open execution</Btn></div></>}
            <div className="ell-stack"><Btn {...options} icon="trace" onClick={()=>go("trace",{id:item.id,direction:item.kind==="measure"?"Both directions":"Upstream",depth:8,baseline:evidenceBaseline??view.baseline})}>Trace to source requirement</Btn></div>
          </>;
        }}</Loading>
      </Panel>
    </div>
  </>;
}


const evidenceLabels=["Deliverables","Evidence","Traceability","Consistency","Quality","Tailoring applied"];
function Assessment(props) {
  const {React,ui,state,view,patch,go,mutate,readOnly,exportReport}=props;
  const groups=["All","L1","L2","L3"], group=view.tab||"All", options={React,ui};
  const rows=state.processes.filter(p=>p.state!=="Not applicable"), openFindings=state.items.filter(i=>i.finding?.status==="Open");
  const selected=rows.find(p=>p.code===view.process)??rows.find(p=>p.code==="SYS.2")??rows[0];
  const relevant=e=>group==="All"||e.attribute.startsWith("PA "+group.slice(-1)+".");
  const all=rows.flatMap(p=>state.assessments[p.code]??[]).filter(relevant).filter(e=>e.state!=="N/A");
  const selectedEvidence=(state.assessments[selected?.code]??[]).filter(relevant);
  const selectedFindings=state.items.filter(i=>i.finding&&i.process===selected?.code), columns=evidenceLabels.filter(label=>all.some(e=>e.label===label)), start=view.page??0;
  function improvement(source){
    ask(props,"Create improvement action",[
      fieldSpec("title","Finding title",source?"Review "+source.label.toLowerCase():""),fieldSpec("action","Improvement action","",{multiline:true}),
      fieldSpec("owner","Owner",selected.owner,{options:state.users.map(u=>[u.id,u.name])}),fieldSpec("due","Due date","",{type:"date",required:false})
    ],v=>mutate({name:"finding",process:selected.code,attribute:source?.attribute,source:source?.source,...v}));
  }
  function reviewEvidence(e){
    const choices=state.items.filter(i=>i.kind!=="anchor").map(i=>[i.id,i.code+" · "+i.title]);
    ask(props,"Review "+selected.code+" evidence",[
      fieldSpec("status","Evidence status",e.state,{options:["Ready","Review","Missing","N/A"]}),
      fieldSpec("source","Evidence source",e.source,{options:[["","No evidence attached"],...choices]}),
      fieldSpec("rationale","Review rationale","",{multiline:true})
    ],v=>mutate({name:"assessment-evidence",process:selected.code,label:e.label,source:v.source,state:v.status,rationale:v.rationale}));
  }
  return <>
    <Heading React={React} title="Assessment Readiness" sub={"Automotive SPICE® "+state.model+" · Internal evidence review · "+projectSubtitle(props)} actions={<Btn {...options} primary icon="download" onClick={()=>exportReport("assessment")}>Create evidence report</Btn>}/>
    <div className="ell-metrics"><Metric React={React} label="Applied processes" ratio={rows.length} note="Selected release and baseline"/><Metric React={React} label="Evidence ready" ratio={{n:all.filter(e=>e.state==="Ready").length,d:all.length}}/><Metric React={React} label="Open findings" ratio={openFindings.length} note="Under active investigation"/><Metric React={React} label="Manual ratings" ratio={state.assessorRecords.length} note="Recorded assessor opinions"/></div>
    <div className="ell-split"><Panel React={React} title="Process evidence matrix" sub="Work products, reviews, traces and evidence" action={<Toggle React={React} label="Evidence level filter" options={groups} value={group} onChange={tab=>patch({tab,page:0,assessmentLabel:""})}/>}>
      <Table React={React} label="Process evidence matrix" columns={["Process",...columns,"Open gaps"]}>{rows.slice(start*12,(start+1)*12).map(p=>{
        const entries=(state.assessments[p.code]??[]).filter(relevant), gaps=openFindings.filter(g=>g.process===p.code).length;
        return <tr key={p.code} data-selected={p.code===selected?.code}><td><button className="ell-itembutton" onClick={()=>patch({process:p.code,assessmentLabel:""})}><code>{p.code}</code><span>{p.label}</span></button></td>{columns.map(label=>{const e=entries.find(row=>row.label===label);return <td key={label}><button className={"ell-heat-cell "+statusTone(e?.state??"N/A")} aria-label={p.code+" "+label+" "+(e?.state??"N/A")} onClick={()=>patch({process:p.code,assessmentLabel:label})}>{e?.state??"N/A"}</button></td>;})}<td><Badge React={React} text={gaps+" open"} tone={gaps?"warning":"neutral"}/></td></tr>;
      })}</Table><Pages {...options} page={start} total={rows.length} size={12} onChange={page=>patch({page})}/>
    </Panel><Panel React={React} className="ell-inspect">
      {selected&&<><code>{selected.code}</code><h2>{selected.label}</h2><small>Readiness review · PAM {state.model}</small>
      <div className="ell-stack">{selectedEvidence.filter(e=>!view.assessmentLabel||e.label===view.assessmentLabel).map(e=><div key={e.label} className="ell-link-row"><div className="ell-between"><strong>{e.label}</strong><Badge React={React} text={e.state}/></div><small>{e.attribute}</small><div className="ell-actions">{e.source&&<Btn {...options} onClick={()=>props.toItem(e.source)}>{one(state.items,e.source)?.code??"Open evidence"}</Btn>}<Btn {...options} disabled={readOnly} onClick={()=>reviewEvidence(e)}>Review evidence</Btn>{e.state!=="Ready"&&<Btn {...options} disabled={readOnly} onClick={()=>improvement(e)}>Create action</Btn>}</div></div>)}</div>
      <div className="ell-stack"><Btn {...options} primary icon="plus" disabled={readOnly} onClick={()=>improvement()}>Create improvement action</Btn><Btn {...options} icon="trace" onClick={()=>go("trace",{process:selected.code,tab:"Gaps"})}>Open trace checks</Btn></div>
      {selectedFindings.map(f=><div key={f.id} className="ell-link-row"><div className="ell-between"><code>{f.code}</code><Badge React={React} text={f.finding.status}/></div><strong>{f.title}</strong><small>{f.finding.due?"Due "+f.finding.due:ownerName(state.users,f.owner)}</small><p>{f.finding.action||f.body}</p>{f.finding.status==="Open"&&<Btn {...options} disabled={readOnly} onClick={()=>ask(props,"Close "+f.code,[fieldSpec("action","Completion evidence","",{multiline:true})],v=>mutate({name:"finding-close",id:f.id,...v}))}>Record closure</Btn>}</div>)}
      <div className="ell-stack-title"><h3>Assessor opinions</h3><small>Manually recorded assessment ratings</small></div>
      {state.assessorRecords.filter(r=>r.process===selected.code).map((r,i)=><div className="ell-link-row" key={i}><strong>{r.attribute+" · "+r.rating}</strong><small>{ownerName(state.users,r.assessor)+" · "+plainDate(r.at)}</small><p>{r.note}</p></div>)}
      <div className="ell-stack"><Btn {...options} disabled={readOnly} onClick={()=>ask(props,"Record assessor opinion",[
        fieldSpec("actor","Assessor",state.users[0].id,{options:state.users.map(u=>[u.id,u.name])}),fieldSpec("attribute","Process attribute","PA 1.1",{options:["PA 1.1","PA 2.1","PA 2.2","PA 3.1","PA 3.2"]}),fieldSpec("rating","Rating","L",{options:["N","P","L","F"]}),fieldSpec("note","Evidence and scope","",{multiline:true})
      ],v=>mutate({name:"assessor",process:selected.code,...v}))}>Record manual opinion</Btn></div></>}
    </Panel></div>
  </>;
}
function Planning(props){
  const {React,ui,state,project,view,go,exportReport}=props;
  const options={React,ui}, m=state.metrics;
  return <>
    <Heading React={React} title={view.process==="MAN.6"?"Measurement":view.process==="SPL.2"?"Product Release":"Project Management"} sub={projectSubtitle(props)} actions={<Btn {...options} primary icon="download" onClick={()=>exportReport("portfolio")}>Export project report</Btn>}/>
    <div className="ell-metrics"><Metric React={React} label="Deliverables" ratio={m.deliverables}/><Metric React={React} label="Trace coverage" ratio={m.trace}/><Metric React={React} label="Verification executed" ratio={m.execution}/><Metric React={React} label="Next milestone" ratio={project.milestoneDate} note={project.milestone}/></div>
    <Panel React={React} title="Milestone plan and actual progress"><Table React={React} label="Process progress" columns={["Process","Owner","Approved / planned","State"]}>{state.processes.map(p=><tr key={p.code}><td><button type="button" className="ell-itembutton" onClick={()=>go("lifecycle",{process:p.code})}><code>{p.code}</code><span>{p.label}</span></button></td><td>{ownerName(state.users,p.owner)}</td><td>{p.approved+" / "+p.planned}</td><td><Badge React={React} text={p.state}/></td></tr>)}</Table></Panel>
  </>;
}


function Risks(props){
  const {React,ui,state,view,patch,invoke,input,toItem,mutate,readOnly,go}=props, options={React,ui};
  const current=one(state.items,view.id);
  const mode=view.tab||(view.process==="SUP.9"||current?.kind==="problem"?"Problems":view.process==="SUP.1"?"Quality":"Risks");
  const kind=({Risks:"risk",Problems:"problem",Quality:"finding"})[mode];
  const items=state.items.filter(i=>i.kind===kind&&matches(i,view.query)), selected=one(items,view.id)??items[0];
  const detail=useResource(React,invoke,"detail",{...input,id:selected?.id},Boolean(selected)), page=view.page??0;
  function riskDialog(item){
    const v=item?.risk, choices=["1","2","3","4","5"];
    ask(props,item?"Edit "+item.code:"New risk",[...(item?[]:[fieldSpec("title","Risk title")]),fieldSpec("likelihood","Likelihood",String(v?.likelihood??3),{options:choices}),fieldSpec("impact","Impact",String(v?.impact??3),{options:choices}),fieldSpec("residualLikelihood","Residual likelihood",String(v?.residualLikelihood??2),{options:choices}),fieldSpec("residualImpact","Residual impact",String(v?.residualImpact??3),{options:choices}),fieldSpec("strategy","Mitigation",v?.strategy??"",{multiline:true})],v=>mutate({name:"risk",id:item?.id,...v,likelihood:Number(v.likelihood),impact:Number(v.impact),residualLikelihood:Number(v.residualLikelihood),residualImpact:Number(v.residualImpact)}));
  }
  return <>
    <Heading React={React} title="Problems, Risk & Quality" sub={"MAN.5 · SUP.9 · SUP.1 · "+projectSubtitle(props)} actions={mode==="Risks"?<Btn {...options} primary icon="plus" disabled={readOnly} onClick={()=>riskDialog()}>New risk</Btn>:<Btn {...options} onClick={()=>go(mode==="Problems"?"verification":"assessment")}>{mode==="Problems"?"Open verification":"Open assessment"}</Btn>}/>
    <div className="ell-split"><Panel React={React} title={mode==="Risks"?"Risk matrix":mode} sub={mode==="Risks"?"Current likelihood × impact":"Issues and corrective actions"} action={<Toggle React={React} label="Governance view" value={mode} options={["Risks","Problems","Quality"]} onChange={tab=>patch({tab,id:"",page:0,query:""})}/>}>
      {mode==="Risks"&&<div className="ell-riskmap" aria-label="Risk matrix"><span/>{[1,2,3,4,5].map(x=><span key={x}>{x}</span>)}{[5,4,3,2,1].map(l=><React.Fragment key={l}><span>{l} · Likelihood</span>{[1,2,3,4,5].map(j=>{
        const cell=items.filter(i=>i.risk.likelihood===l&&i.risk.impact===j);
        return <div key={j} className={"ell-risk-cell "+(l*j>=12?"danger":l*j>=5?"warning":"success")}>{cell.length?cell.map(i=><button key={i.id} aria-pressed={selected?.id===i.id} onClick={()=>patch({id:i.id})}>{i.code}</button>):"·"}</div>;
      })}</React.Fragment>)}</div>}
      <div className="ell-toolbar"><Search React={React} label={"Find "+mode.toLowerCase()} value={view.query} onChange={query=>patch({query,page:0,id:""})}/></div>
      <Table React={React} label={mode} columns={["Artifact","Status","Owner"]}>{items.slice(page*10,(page+1)*10).map(i=><tr key={i.id} data-selected={selected?.id===i.id}><td><ItemButton React={React} item={i} onClick={()=>patch({id:i.id})}/></td><td>{i.problem?.state??i.finding?.status??i.risk.likelihood+" × "+i.risk.impact}</td><td>{ownerName(state.users,i.owner)}</td></tr>)}</Table>
      {!items.length&&<Empty {...options} text={"No "+mode.toLowerCase()+" match this scope"}/>}<Pages {...options} page={page} total={items.length} size={10} onChange={page=>patch({page})}/>
    </Panel><Panel React={React} className="ell-inspect"><Loading {...options} state={detail}>{({item,connected})=><>
      <code>{item.code}</code><h2>{item.title}</h2><p className="ell-text">{item.body}</p><Fact React={React} label="Owner">{ownerName(state.users,item.owner)}</Fact>
      {item.risk&&<><Fact React={React} label="Likelihood × impact">{item.risk.likelihood+" × "+item.risk.impact}</Fact><Fact React={React} label="Target residual risk">{item.risk.residualLikelihood+" × "+item.risk.residualImpact}</Fact><p className="ell-text">{item.risk.strategy}</p><Btn {...options} disabled={readOnly} onClick={()=>riskDialog(item)}>Review mitigation</Btn></>}
      {item.problem&&<><Fact React={React} label="Severity">{item.problem.severity}</Fact><Fact React={React} label="Cause">{item.problem.cause}</Fact><p className="ell-text">{item.problem.action}</p>
        <Btn {...options} disabled={readOnly} onClick={()=>ask(props,"Update "+item.code,[fieldSpec("cause","Root cause",item.problem.cause,{multiline:true}),fieldSpec("action","Corrective action",item.problem.action,{multiline:true}),fieldSpec("retest","Passing retest","",{options:[["","No retest"],...state.items.filter(x=>x.kind==="execution").map(x=>[x.id,x.code+" "+x.title])] }),fieldSpec("closed","Status",item.problem.state,{options:["Open","Closed"]})],v=>mutate({name:"problem-update",id:item.id,...v,closed:v.closed==="Closed"}))}>Update problem and retest</Btn></>}
      {item.finding&&<><Fact React={React} label="Action status">{item.finding.status}</Fact><p className="ell-text">{item.finding.action}</p><Btn {...options} onClick={()=>go("assessment",{process:item.process,id:item.id})}>Open corrective action</Btn></>}
      <div className="ell-stack-title"><h3>Related engineering records</h3></div>{connected.map(l=><div key={l.id} className="ell-link-row"><ItemButton React={React} item={l.peer} onClick={()=>toItem(l.peer)}/><small>{l.type}</small></div>)}
    </>}</Loading></Panel></div>
  </>;
}
